  static string cacheKey,failureKey,failureMessage;static Bitmap cached;static Rectangle cachedClip;static Rectangle[] cachedBounds;static Dictionary<int,Rectangle> sceneBounds;public static int ProcessStarts;
  static string N(double x){return x.ToString("R",CultureInfo.InvariantCulture);}static string Q(string s){return "\""+s.Replace("\"","\\\"")+"\"";}
