   var page=new[]{new PointF(0,0),new PointF(pageWidth,0),new PointF(0,pageHeight)};g.TransformPoints(CoordinateSpace.Device,CoordinateSpace.World,page);double a=(page[1].X-page[0].X)/612.0,b=(page[1].Y-page[0].Y)/612.0,c=(page[0].X-page[2].X)/792.0,d=(page[0].Y-page[2].Y)/792.0;var job=NativePrintJob.Active;string physical=job==null?"":job.IncludedProgramPhysicalSpace(pageWidth,pageHeight);string ps="%!PS\n<< /PageSize ["+clip.Width+" "+clip.Height+"] >> setpagedevice\n["+N(a)+" "+N(-b)+" "+N(c)+" "+N(-d)+" "+N(page[2].X-clip.Left)+" "+N(clip.Height-page[2].Y+clip.Top)+"] concat\n"+(scene==null?"":NativePostScriptBounds.Program)+physical+preparedPrograms+"\nshowpage\n";if(measure){int split=ps.IndexOf("] concat\n",StringComparison.Ordinal)+9;string setup=ps.Substring(ps.IndexOf("\n[")+1,split-(ps.IndexOf("\n[")+1));foreach(string program in programs)ps+="initgraphics\n"+setup+physical+program+"\nshowpage\n";}string exe=GhostscriptTextRenderer.Executable,key=exe+new FileInfo(exe).LastWriteTimeUtc.Ticks+ps+fontmap;
