   var state=g.Save();try{g.ResetTransform();g.PageUnit=GraphicsUnit.Pixel;g.PageScale=1;g.DrawImageUnscaled(cached,cachedClip.Left,cachedClip.Top);NativeItemBounds.Image(g,cached,cachedClip.Left,cachedClip.Top);if(measure)for(int n=0;n<items.Count;n++){NativeItemBounds.Select(items[n]);NativeItemBounds.DeviceRectangle(g,cachedBounds[n],cachedClip.Left,cachedClip.Top);}if(measure)NativeItemBounds.Select(null);if(scene!=null&&sceneBounds!=null)foreach(var bounds in sceneBounds)if(bounds.Key<=scene.Score.Items.Count){NativeItemBounds.Select(scene.Score.Items[bounds.Key-1]);NativeItemBounds.DeviceRectangle(g,bounds.Value,cachedClip.Left,cachedClip.Top);}NativeItemBounds.Select(null);}finally{g.Restore(state);}
  }
 }
}


